"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface MessageThreadProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Springt bij nieuwe berichten naar beneden (standaard aan). */
  autoScroll?: boolean;
}

/**
 * MessageThread — verloop van een gesprek: ticket, interne notities, chat.
 * Combineert met Composer voor de invoer eronder.
 */
export const MessageThread = React.forwardRef<HTMLDivElement, MessageThreadProps>(function MessageThread(
  { autoScroll = true, className, children, ...rest },
  ref
) {
  const eigen = React.useRef<HTMLDivElement>(null);
  const aantal = React.Children.count(children);

  React.useEffect(() => {
    if (!autoScroll) return;
    const node = eigen.current;
    if (node) node.scrollTop = node.scrollHeight;
  }, [autoScroll, aantal]);

  return (
    <div
      ref={(node) => {
        eigen.current = node;
        if (typeof ref === "function") ref(node as HTMLDivElement);
        else if (ref) (ref as React.RefObject<HTMLDivElement | null>).current = node;
      }}
      className={cn("lui-thread", className)}
      {...rest}
    >
      {children}
    </div>
  );
});

export interface MessageDayProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
}

/** Scheiding tussen dagen: "Vandaag", "20 maart". */
export const MessageDay = React.forwardRef<HTMLDivElement, MessageDayProps>(function MessageDay(
  { className, children, ...rest },
  ref
) {
  return (
    <div ref={ref} className={cn("lui-thread-day", className)} {...rest}>
      <span>{children}</span>
    </div>
  );
});

export interface MessageProps extends React.HTMLAttributes<HTMLDivElement> {
  /** "me" rechts en in accentkleur, "them" links, "system" gecentreerd. */
  from?: "me" | "them" | "system";
  author?: React.ReactNode;
  time?: React.ReactNode;
  avatar?: React.ReactNode;
  /** Statusregel onder de bel, bijvoorbeeld "gelezen" of "verzonden". */
  status?: React.ReactNode;
  /** Interne notitie: amber, niet zichtbaar voor de klant. */
  internal?: boolean;
  /** Bijlagen of knoppen onder de tekst. */
  footer?: React.ReactNode;
}

export const Message = React.forwardRef<HTMLDivElement, MessageProps>(function Message(
  { from = "them", author, time, avatar, status, internal, footer, className, children, ...rest },
  ref
) {
  if (from === "system") {
    return (
      <div ref={ref} className={cn("lui-thread-system", className)} {...rest}>
        {children}
        {time && <time className="lui-thread-system-time">{time}</time>}
      </div>
    );
  }

  return (
    <div ref={ref} className={cn("lui-message", `lui-message-${from}`, className)} {...rest}>
      {avatar && <span className="lui-message-avatar">{avatar}</span>}
      <div className="lui-message-column">
        {(author || time) && (
          <div className="lui-message-meta">
            {author && <span className="lui-message-author">{author}</span>}
            {time && <time className="lui-message-time">{time}</time>}
          </div>
        )}
        <div className={cn("lui-message-bubble", internal && "lui-message-internal")}>
          {internal && <span className="lui-message-internal-label">Interne notitie</span>}
          {children}
          {footer && <div className="lui-message-footer">{footer}</div>}
        </div>
        {status && <span className="lui-message-status">{status}</span>}
      </div>
    </div>
  );
});

/* ============================ MessageThread ============================ */
.lui-thread {
  display: flex; flex-direction: column; gap: 14px;
  padding: 18px; overflow-y: auto;
  background: var(--surface-2);
}

.lui-thread-day {
  display: flex; align-items: center; gap: 12px;
  font-size: 11.5px; font-weight: 650; letter-spacing: .04em;
  text-transform: uppercase; color: var(--text-3);
}
.lui-thread-day::before,
.lui-thread-day::after { content: ""; flex: 1; height: 1px; background: var(--border); }

.lui-thread-system {
  align-self: center; display: inline-flex; align-items: center; gap: 8px;
  padding: 5px 11px; border-radius: var(--r-full);
  background: var(--surface-3); color: var(--text-3); font-size: 12.5px;
}
.lui-thread-system-time { font-size: 11.5px; opacity: .8; }

/* ---------- Bericht ---------- */
.lui-message { display: flex; gap: 10px; max-width: 78%; }
.lui-message-them { align-self: flex-start; }
.lui-message-me { align-self: flex-end; flex-direction: row-reverse; }

.lui-message-avatar { flex: none; align-self: flex-end; }
.lui-message-column { display: flex; flex-direction: column; min-width: 0; gap: 4px; }

.lui-message-meta { display: flex; align-items: baseline; gap: 8px; padding: 0 2px; }
.lui-message-me .lui-message-meta { justify-content: flex-end; }
.lui-message-author { font-size: 12.5px; font-weight: 600; color: var(--text-2); }
.lui-message-time { font-size: 11.5px; color: var(--text-3); }

.lui-message-bubble {
  padding: 10px 13px; border-radius: var(--r-md);
  background: var(--surface); border: 1px solid var(--border);
  font-size: 13.5px; line-height: 1.55; color: var(--text);
  overflow-wrap: anywhere;
}
.lui-message-them .lui-message-bubble { border-bottom-left-radius: var(--r-xs); }
.lui-message-me .lui-message-bubble {
  background: var(--accent); border-color: var(--accent);
  color: var(--accent-fg); border-bottom-right-radius: var(--r-xs);
}

.lui-message-internal {
  background: var(--amber-tint); border-color: var(--amber-border); color: var(--text);
}
.lui-message-me .lui-message-internal { color: var(--text); }
.lui-message-internal-label {
  display: block; margin-bottom: 4px;
  font-size: 10.5px; font-weight: 700; letter-spacing: .04em;
  text-transform: uppercase; color: var(--amber);
}

.lui-message-footer {
  margin-top: 8px; padding-top: 8px;
  border-top: 1px solid color-mix(in srgb, currentColor 14%, transparent);
  display: flex; flex-wrap: wrap; gap: 8px; font-size: 12.5px;
}
.lui-message-status { font-size: 11.5px; color: var(--text-3); padding: 0 2px; }
.lui-message-me .lui-message-status { text-align: right; }

@media (max-width: 560px) {
  .lui-message { max-width: 92%; }
}

/* ---------- Motion: berichten ploppen binnen vanaf de kant van de afzender ---------- */
.lui-message { animation: lui-message-in .38s var(--ease-pop) backwards; }
.lui-message-them { transform-origin: bottom left; }
.lui-message-me { transform-origin: bottom right; }
@keyframes lui-message-in { from { opacity: 0; transform: translateY(8px) scale(.94); } to { opacity: 1; transform: none; } }
.lui-thread > :nth-child(2) { animation-delay: 50ms; }
.lui-thread > :nth-child(3) { animation-delay: 100ms; }
.lui-thread > :nth-child(4) { animation-delay: 150ms; }
.lui-thread > :nth-child(5) { animation-delay: 200ms; }
.lui-thread > :nth-child(n + 6) { animation-delay: 250ms; }
.lui-thread-day, .lui-thread-system { animation: lui-overlay-in .4s var(--ease) backwards; }
